export interface UserMembershipResponse {
  tenantId: string;
  tenantName: string;
  tenantSlug: string;
  tenantStatus: UserMembershipResponseTenantStatus;
  role: RoleResponse;
  joinedAt: string;
  lastOwner: boolean;
}

/**
 * One user for the user detail screen: as in the list, with when a system admin suspended them and that system admin's names
 * (null when the user is not suspended), and every membership by the tenant's name.
 */
export interface UserDetailResponse {
  id: string;
  /** @nullable */
  email: string | null;
  /** @nullable */
  firstName: string | null;
  /** @nullable */
  lastName: string | null;
  status: UserResponseStatus;
  isSystemAdmin: boolean;
  membershipCount: number;
  createdAt: string;
  /** @nullable */
  suspendedAt: string | null;
  suspendedBy: null | UserNameResponse;
  memberships: UserMembershipResponse[];
}

